"""AdvisorAgent — turns analysis into structured advice + a narrative.

Produces the final :class:`AdvisoryReport`:
  * ``risk_posture`` — an overall assessment derived from anomaly severity.
  * ``recommendations`` — structured, prioritized actions mapped from findings.
  * ``summary_narrative`` — advisor-friendly prose. Generated by the LLM when a
    key is configured; otherwise a deterministic template (``narrative_source``
    records which was used).

The LLM only *phrases* already-computed findings; all numbers and
recommendations are deterministic, so the advice is reproducible and auditable.
"""

from __future__ import annotations

import json
from datetime import datetime, timezone

from ..config import settings
from ..context import SessionContext
from ..schemas import (
    SEVERITY_HIGH,
    SEVERITY_LOW,
    SEVERITY_MEDIUM,
    SEVERITY_ORDER,
    STATUS_SUCCESS,
    AdvisoryReport,
    HITLRecord,
    Recommendation,
)
from .base import Agent, AgentResult

_POSTURE = {
    None: "stable",
    SEVERITY_LOW: "low-concern",
    SEVERITY_MEDIUM: "elevated",
    SEVERITY_HIGH: "high",
}

_SYSTEM_PROMPT = (
    "You are a prudent wealth advisor assistant. Write a concise, professional "
    "advisory summary (2-3 short paragraphs) for an internal advisor, based ONLY "
    "on the structured findings provided. Do not invent numbers, holdings, or "
    "facts beyond what is given. Be specific about the key risks and the "
    "recommended actions, and keep a measured, non-alarmist tone."
)


class AdvisorAgent(Agent):
    name = "advisor"

    def execute(self, context: SessionContext) -> AgentResult:
        result = AgentResult(agent=self.name)
        profile = context.profile
        analysis = context.analysis
        if profile is None or analysis is None:  # pragma: no cover
            result.status = "failed"
            result.errors.append("missing profile or analysis for advisory")
            return result

        anomalies = sorted(
            analysis.anomalies,
            key=lambda a: SEVERITY_ORDER.get(a.severity, 0),
            reverse=True,
        )
        risk_posture = _POSTURE[analysis.highest_severity]

        recommendations = self._build_recommendations(context, anomalies)
        narrative, source = self._build_narrative(
            context, risk_posture, anomalies, recommendations
        )

        report = AdvisoryReport(
            run_id=context.run_id,
            client_id=profile.financial.client_id,
            client_name=profile.financial.name,
            generated_at=datetime.now(timezone.utc).isoformat(timespec="seconds"),
            risk_posture=risk_posture,
            summary_narrative=narrative,
            narrative_source=source,
            recommendations=recommendations,
            anomalies=anomalies,
            metrics=analysis.metrics,
            degraded_mode=profile.degraded,
            warnings=profile.warnings,
            hitl=context.hitl or HITLRecord(),
            meta={
                "memory_comparison": analysis.memory_comparison,
                "elapsed_seconds": context.elapsed_seconds,
                "crm_available": profile.crm is not None,
            },
        )
        context.report = report
        result.output = report
        result.status = STATUS_SUCCESS
        self.log.info(
            "advisory ready: posture=%s, %d recommendation(s), narrative=%s",
            risk_posture,
            len(recommendations),
            source,
        )
        return result

    # -- recommendations ----------------------------------------------------
    def _build_recommendations(
        self, context: SessionContext, anomalies: list
    ) -> list[Recommendation]:
        recs: list[Recommendation] = []
        for a in anomalies:
            recs.append(
                Recommendation(
                    title=a.title,
                    action=a.recommendation_hint or "Review with the client.",
                    rationale=a.explanation,
                    priority=a.severity,
                    related_anomaly_type=a.type,
                )
            )

        profile = context.profile
        if profile and profile.crm and profile.crm.kyc_status != "verified":
            recs.append(
                Recommendation(
                    title="Complete KYC verification",
                    action="Follow up to complete KYC before acting on advice.",
                    rationale=f"KYC status is '{profile.crm.kyc_status}'.",
                    priority=SEVERITY_MEDIUM,
                )
            )

        if not recs:
            recs.append(
                Recommendation(
                    title="No action required",
                    action="Maintain current strategy; review at the next cycle.",
                    rationale="No anomalies or risk signals were detected.",
                    priority=SEVERITY_LOW,
                )
            )
        return recs

    # -- narrative (LLM optional) ------------------------------------------
    def _build_narrative(
        self, context: SessionContext, posture: str, anomalies: list, recs: list
    ) -> tuple[str, str]:
        if settings.llm_enabled and self.tools.has("llm"):
            prompt = self._llm_prompt(context, posture, anomalies, recs)
            res = self.tools.get("llm").run(system=_SYSTEM_PROMPT, prompt=prompt)
            self._trace_tool(context, res)
            if res.ok and res.data:
                return res.data, "llm"
            self.log.warning(
                "LLM narrative unavailable (%s); using template.", res.error
            )
        return self._template_narrative(context, posture, anomalies, recs), "template"

    def _llm_prompt(
        self, context: SessionContext, posture: str, anomalies: list, recs: list
    ) -> str:
        profile = context.profile
        payload = {
            "client": {
                "name": profile.financial.name,
                "risk_tolerance": profile.crm.risk_tolerance if profile.crm else "unknown",
            },
            "overall_risk_posture": posture,
            "metrics": context.analysis.metrics.to_dict(),
            "anomalies": [a.to_dict() for a in anomalies],
            "recommendations": [r.to_dict() for r in recs],
            "trend_vs_last_review": context.analysis.memory_comparison,
            "data_quality_warnings": profile.warnings,
        }
        return (
            "Write the advisory summary from these findings:\n\n"
            + json.dumps(payload, indent=2, default=str)
        )

    def _template_narrative(
        self, context: SessionContext, posture: str, anomalies: list, recs: list
    ) -> str:
        profile = context.profile
        m = context.analysis.metrics
        lines: list[str] = []

        risk_tol = profile.crm.risk_tolerance if profile.crm else "unknown"
        lines.append(
            f"{profile.financial.name} holds a portfolio of approximately "
            f"${m.total_aum:,.0f} across {m.holdings_count} holding(s), with "
            f"{m.cash_pct:.0%} in cash. Stated risk tolerance: {risk_tol}. "
            f"Overall risk posture is assessed as {posture.upper()}."
        )

        if anomalies:
            top = anomalies[: min(3, len(anomalies))]
            findings = "; ".join(f"{a.title} ({a.severity.lower()})" for a in top)
            lines.append(f"Key findings: {findings}.")
        else:
            lines.append("No anomalies or risk signals were detected this review.")

        comp = context.analysis.memory_comparison or {}
        if comp.get("first_review"):
            lines.append("This is the first review on record for this client.")
        elif comp.get("recurring_anomaly_types"):
            lines.append(
                "Recurring since the last review: "
                + ", ".join(comp["recurring_anomaly_types"]) + "."
            )

        action_items = "; ".join(f"{r.title} — {r.action}" for r in recs[:3])
        lines.append(f"Recommended next steps: {action_items}")

        if profile.degraded:
            lines.append(
                "Note: this review ran in degraded mode due to missing context — "
                + " ".join(profile.warnings)
            )
        return "\n\n".join(lines)
